import NextAuth from "next-auth";
import GoogleProvider from "next-auth/providers/google";
import CredentialsProvider from "next-auth/providers/credentials";

export const authOptions = {
  providers: [
    GoogleProvider({
      clientId: process.env.GOOGLE_CLIENT_ID,
      clientSecret: process.env.GOOGLE_CLIENT_SECRET,
    }),
    CredentialsProvider({
      name: "Email and password",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" },
      },
      async authorize(credentials) {
        if (!credentials?.email || !credentials?.password) return null;
        const response = await fetch(`${process.env.AUTH_API_URL}/auth/login`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email: credentials.email, password: credentials.password }),
          cache: "no-store",
        });
        if (!response.ok) return null;
        const result = await response.json();
        const user = result?.user;
        if (!user?.id || !user?.email) return null;
        return { id: String(user.id), name: user.name ?? null, email: user.email, image: user.image ?? null, role: user.role ?? "user" };
      },
    }),
  ],
  session: { strategy: "jwt" },
};

export default NextAuth(authOptions);

async authorize(credentials) {
  const email = credentials?.email?.trim().toLowerCase();
  const password = credentials?.password;
  if (!email || typeof password !== "string" || !password) return null;

  const response = await fetch(`${process.env.AUTH_API_URL}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
    cache: "no-store",
  });
  if (!response.ok) return null;

  const result = await response.json();
  const user = result?.user;
  if (!user?.id || !user?.email) return null;
  return {
    id: String(user.id),
    name: user.name ?? null,
    email: user.email,
    image: user.image ?? null,
    role: user.role ?? "user",
  };
}

callbacks: {
  async signIn({ user, account, profile }) {
    if (account?.provider === "google") {
      return Boolean(user?.email && profile?.email_verified);
    }
    return Boolean(user?.email);
  },
},

callbacks: {
  async jwt({ token, user, account }) {
    if (user) {
      token.userId = user.id;
      if (user.role) token.role = user.role;
    }
    if (account) token.provider = account.provider;
    return token;
  },
},

callbacks: {
  async session({ session, token }) {
    if (session.user) {
      session.user.id = token.userId ?? token.sub ?? "";
      session.user.role = token.role ?? "user";
    }
    session.provider = token.provider ?? null;
    return session;
  },
},

callbacks: {
  async redirect({ url, baseUrl }) {
    if (url.startsWith("/")) return `${baseUrl}${url}`;
    try {
      if (new URL(url).origin === baseUrl) return url;
    } catch {}
    return baseUrl;
  },
},

events: {
  async signIn({ user, account, isNewUser }) {
    console.info("auth.signIn", {
      userId: user?.id ?? null,
      provider: account?.provider ?? null,
      isNewUser: Boolean(isNewUser),
    });
  },
},

